-- Fiche Décrire une image (CE2) - anglais, notion 'en_decrire_position'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce2', 'english', 'Décrire une image', $fiche$
